/**
 * Preserve exact frozen C artifacts across explicit batch-array initialization.
 *
 * @file
 */
import { sha256 } from "../../src/capsule/node.mjs";

/**
 * Recover historical generated bytes only when their complete digest matches.
 * Unknown edits remain visible to each immutable receipt's verification.
 *
 * @param source - Current generated C translation unit or probe.
 * @param expected - Source digest from the frozen execution receipt.
 */
export const beforeOwnedTransferBatchInitialization = (source, expected) => {
	if(sha256(source) === expected) return source;
	const prior = source.replace(/^ {2}lb_owned_batch \*batches\[(\d+)\] = \{0\}; size_t batch_count = 0;$/gmu
		, "  lb_owned_batch *batches[$1]; size_t batch_count = 0;");
	return sha256(prior) === expected ? prior : source;
};

/**
 * Keep the source inventory paired with the authenticated historical body.
 *
 * @param generated - Current generated public C package.
 * @param expected - Source digest from the frozen execution receipt.
 */
export const historicalOwnedTransferPackage = (generated, expected) => {
	const prior = beforeOwnedTransferBatchInitialization(generated.source, expected);
	if(prior === generated.source) return generated;
	return { ...generated, source: prior
		, files: Object.fromEntries(Object.entries(generated.files).map(([path, source]) =>
			[path, source === generated.source ? prior : source])) };
};
